import json
import xml.etree.ElementTree as ET
from email.utils import parsedate_to_datetime

NS = {"anibt": "https://anibt.net/xmlns/rss/1.0/"}


def text(item, tag):
    """Read a direct child element's text."""
    child = item.find(tag, NS)
    if child is None or child.text is None:
        return ""
    return child.text.strip()


def texts(item, tag):
    """Read every occurrence of a repeated child element."""
    return [
        child.text.strip()
        for child in item.findall(tag, NS)
        if child is not None and child.text
    ]


def as_list(value):
    """Normalise a filter value into a list of strings."""
    if not value:
        return []
    if isinstance(value, (list, tuple, set)):
        return [str(v).strip() for v in value if str(v).strip()]
    return [part.strip() for part in str(value).split(",") if part.strip()]


def human_size(value):
    """Format a byte count as a human readable size."""
    try:
        size = float(value)
    except (TypeError, ValueError):
        return ""
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if size < 1024 or unit == "TB":
            return f"{int(size)} B" if unit == "B" else f"{size:.2f} {unit}"
        size /= 1024.0
    return ""


def matches_keyword(title, keyword):
    """Case-insensitive match of every whitespace-separated word."""
    if not keyword:
        return True
    haystack = title.casefold()
    return all(word.casefold() in haystack for word in keyword.split())


def published(item):
    """Parse the RSS pubDate into a sortable timestamp."""
    raw = text(item, "pubDate")
    try:
        return parsedate_to_datetime(raw).timestamp()
    except (TypeError, ValueError):
        return 0.0


def execute(node_id, node_data, context):
    """Parse the AniBT RSS feed and apply the configured filters locally."""
    status = context.get("anibt_status", 200)
    if not 200 <= status < 300:
        raise ValueError(f"AniBT request failed with HTTP {status}")

    raw = context.get("response") or ""
    try:
        root = ET.fromstring(raw)
    except ET.ParseError as exc:
        raise ValueError("AniBT did not return a valid RSS feed") from exc

    keyword = str(context.get("keyword") or "").strip()
    kinds = as_list(context.get("kind")) or ["anime"]
    resolutions = as_list(context.get("resolution"))
    languages = as_list(context.get("language"))
    subtitles = as_list(context.get("subtitle"))
    formats = as_list(context.get("format"))
    sort_field = str(context.get("sort_field") or "publishedAt")
    sort_order = str(context.get("sort_order") or "desc")

    records = []
    for item in root.iter("item"):
        release_id = text(item, "anibt:releaseId") or text(item, "guid")
        title = text(item, "title")
        if not release_id or not title:
            continue
        if not matches_keyword(title, keyword):
            continue

        kind = text(item, "anibt:type") or "anime"
        if kind not in kinds:
            continue
        resolution = text(item, "anibt:resolution")
        if resolutions and resolution not in resolutions:
            continue
        language = texts(item, "anibt:language")
        if languages and not (set(language) & set(languages)):
            continue
        subtitle = text(item, "anibt:subtitle")
        if subtitles and subtitle not in subtitles:
            continue
        file_format = text(item, "anibt:format")
        if formats and file_format not in formats:
            continue

        misc = []
        if resolution:
            misc.append(resolution)
        if subtitle and subtitle.upper() != "NONE":
            misc.append(subtitle)
        if file_format:
            misc.append(file_format)
        misc.extend(texts(item, "anibt:customTag"))

        try:
            raw_size = float(text(item, "anibt:fileSize") or 0)
        except ValueError:
            raw_size = 0.0

        records.append((
            published(item),
            raw_size,
            {
                "id": release_id,
                "title": title,
                "link": text(item, "anibt:torrentUrl") or text(item, "anibt:releasePageUrl"),
                "size": human_size(text(item, "anibt:fileSize")),
                "misc": " \u00b7 ".join(dict.fromkeys(m for m in misc if m)),
                "category": kind,
                "uploader": text(item, "anibt:groupName"),
                "uploaded_at": text(item, "pubDate"),
            },
        ))

    if sort_field == "fileSize":
        records.sort(key=lambda pair: pair[1], reverse=(sort_order != "asc"))
    else:
        records.sort(key=lambda pair: pair[0], reverse=(sort_order != "asc"))

    items = [record for _, _, record in records]
    context["search_result"] = json.dumps({
        "total": len(items),
        "totalPages": None,
        "page": 1,
        "items": items,
    })
